const ids = a => [...new Set((a||[]).map(x=>String(x?.id??x)))].sort();
const equal = (a,b) => JSON.stringify(ids(a))===JSON.stringify(ids(b));
const fail = message => {throw new Error(message);};
function resultBody(response) {
 if (!response || response.error || !(response.statusCode>=200 && response.statusCode<300)) fail('Request failed'+(response?.statusCode?' (HTTP '+response.statusCode+')':'')+'.');
 const b=typeof response.body==='string'?JSON.parse(response.body):response.body;
 if (!b || b.success===false || b.error) fail('The service did not confirm success.');
