function currentRecord(s,b) {
 if(b.id!==s.recordId) fail('Airtable returned a different campaign.');
 const f=b.fields||{}; let saved;try {saved=JSON.parse(f[FIELD.state]||'{}');}catch{fail('Sender update request is unreadable.');}
 if(saved.requestId!==s.requestId) fail('A newer sender request exists. This run will not overwrite it.');
 if(!equal(saved.senderRecordIds,s.senderRecordIds)||!equal(f[FIELD.senders],s.senderRecordIds)) fail('The sender selection changed during this update. Run the update again with the intended selection.');
 let actionRequest={};try{actionRequest=JSON.parse(f.fldKZKnaFMiAHrDEE||'{}');}catch{}
 const kind=actionRequest.kind, actionTime=Date.parse(actionRequest.requestedAt||'');
 if(['Launch','Pause','Delete'].includes(kind)&&kind===clean(f[FIELD.action])){
