  const fresh=Date.parse(f.fldnHjTrnRPfEqM4e||'')>=actionTime;
  const result=fresh&&(kind==='Launch'?['active','running','live','scheduled','completed'].includes(status):kind==='Pause'?['paused','inactive'].includes(status):status==='deleted');
  const terminal=Date.parse(f.fldqKPdzUqppbItvX||'')>=actionTime&&['completed','failed','error'].includes(clean(f.fldCebt3IMI8ZxdQq).toLowerCase());
  if(!result&&!terminal)fail('Another campaign action is pending. Finish it before updating senders.');
 }
 if(s.campaignId && clean(f[FIELD.campaign])!==s.campaignId) fail('The linked EmailBison campaign changed.');
 if(s.baseUrl && clean(f[FIELD.base]).replace(/\/$/,'')!==s.baseUrl) fail('The campaign server changed.');
 return f;
}
function request(s,stage,kind,method,url,body) {s.stage=stage;return {state:s,action:{kind,method,url,body}};}
function bison(s,stage,method,path,body) {return request(s,stage,'bison',method,s.baseUrl+'/api/campaigns/'+s.campaignId+path,body);}
function readRecord(s,stage) {return request(s,stage,'airtable','GET',CAMPAIGNS+s.recordId+'?returnFieldsByFieldId=true');}
function save(s,stage,status,message) {
 const state={requestId:s.requestId,senderRecordIds:s.senderRecordIds,status,message,requestedAt:s.requestedAt,updatedAt:new Date().toISOString(),executionId:s.executionId,originalStatus:s.originalStatus||null,selectedCount:s.senderRecordIds.length,attachedCount:s.finalIds?.length??null,resumed:!!s.resumed,requiresAttention:!!s.holdLock};
 return request(s,stage,'airtable','PATCH',CAMPAIGNS+s.recordId,{fields:{[FIELD.state]:JSON.stringify(state)}});
}
function list(s,stage,path,page=1) {s.page=page;return request(s,stage,'bison','GET',s.baseUrl+'/api'+path+'?page='+page);}
function pageRows(s,b,property) {
 if(!Array.isArray(b.data)||!b.meta||Number(b.meta.current_page)!==s.page) fail('The sender listing was incomplete.');
 const last=Number(b.meta.last_page), total=Number(b.meta.total);
 if(!Number.isInteger(last)||last<1||last>100||!Number.isInteger(total)||total<0) fail('The sender listing pagination could not be verified.');
 if(s.page===1){s[property]=[];s.listTotal=total;s.listLast=last;}
 if(s.listTotal!==total||s.listLast!==last) fail('Sender accounts changed while pages were being read.');
 s[property].push(...b.data.map(r=>({id:String(r.id),status:clean(r.status).toLowerCase()})));
 if(s.page<last)return false;
 if(s[property].length!==total||ids(s[property]).length!==total) fail('Sender counts did not reconcile across pages.');
 return true;
}
function wait(s,next){s.stage=next;return {state:s,action:{kind:'wait'}};}
function finish(s){const release=s.locked&&!s.holdLock;if(release)s.stage='released';return {state:s,action:{kind:release?'release':'done'}};}
function recovery(s,message){
 s.error=message;s.resumed=false;
 if(s.pauseAttempted){s.recoveryPoll=0;return bison(s,'recoverPause','PATCH','/pause');}
 if(s.authorized)return readRecord(s,'failureRead');
 return finish(s);
}
function advance(input,response) {
 const s=JSON.parse(JSON.stringify(input));
 try {
