  switch(s.stage){
   case 'interrupted':s.error='The sender update execution stopped unexpectedly. Review the run before retrying.';s.pauseAttempted=true;return bison(s,'recoverPause','PATCH','/pause');
   case 'cannotRecover':s.error='The campaign connection changed after an interrupted sender update. Check EmailBison and the retained lock before retrying.';s.holdLock=true;return readRecord(s,'failureRead');
   case 'topupStart':return readRecord(s,'topupLoad');
   case 'topupLoad':{
