    let previous={};try{previous=JSON.parse(f[FIELD.state]||'{}');}catch{fail('Existing sender update state is unreadable.');}
    if(['Requested','Running'].includes(previous.status))fail('A sender update is already pending. Wait for it before topping up.');
    let campaignAction={};try{campaignAction=JSON.parse(f.fldKZKnaFMiAHrDEE||'{}');}catch{}
    const actionKind=campaignAction.kind,actionTime=Date.parse(campaignAction.requestedAt||'');
    if(['Launch','Pause','Delete'].includes(actionKind)&&actionKind===clean(f[FIELD.action])){
     const actionStatus=clean(f.fldZABZwE9SmnwMv3).toLowerCase(),fresh=Date.parse(f.fldnHjTrnRPfEqM4e||'')>=actionTime;
     const actionDone=fresh&&(actionKind==='Launch'?['active','running','live','scheduled','completed'].includes(actionStatus):actionKind==='Pause'?['paused','inactive'].includes(actionStatus):actionStatus==='deleted');
     const actionTerminal=Date.parse(f.fldqKPdzUqppbItvX||'')>=actionTime&&['completed','failed','error'].includes(clean(f.fldCebt3IMI8ZxdQq).toLowerCase());
     if(!actionDone&&!actionTerminal)fail('Another campaign action is pending. Finish it before topping up.');
    }
    s.campaignId=clean(f[FIELD.campaign]);s.baseUrl=clean(f[FIELD.base]).replace(/\/$/,'');s.apiKey=clean(f[FIELD.key]);s.clientId=clean(f[FIELD.client]);
