    if(!s.topupAttached.length)fail('The EmailBison campaign has no attached senders. Attach senders with Update Senders before importing leads.');
    if(s.topupAttached.some(x=>!/^\d+$/.test(x.id)||Number(x.id)<1))fail('The EmailBison campaign returned an invalid attached sender ID.');
    if(s.topupAttached.some(x=>x.status!=='connected'))fail('Every currently attached campaign sender must be connected before importing leads.');
    s.finalIds=ids(s.topupAttached);delete s.topupAttached;
    return readRecord(s,'topupFinalRead');
   }
   case 'topupFinalRead':{
    if(b.id!==s.recordId)fail('Airtable returned a different top-up campaign.');
    const f=b.fields||{};let latest={};try{latest=JSON.parse(f[FIELD.state]||'{}');}catch{fail('Existing sender update state is unreadable.');}
    if(clean(f[FIELD.campaign])!==s.campaignId||clean(f[FIELD.base]).replace(/\/$/,'')!==s.baseUrl||clean(f[FIELD.client])!==s.clientId||clean(f[FIELD.key])!==s.apiKey)fail('The top-up destination or client credential changed during verification.');
    if(['Requested','Running'].includes(latest.status))fail('A sender update started during top-up verification. Retry after it finishes.');
    let campaignAction={};try{campaignAction=JSON.parse(f.fldKZKnaFMiAHrDEE||'{}');}catch{}
    const actionKind=campaignAction.kind,actionTime=Date.parse(campaignAction.requestedAt||'');
    if(['Launch','Pause','Delete'].includes(actionKind)&&actionKind===clean(f[FIELD.action])){
     const actionStatus=clean(f.fldZABZwE9SmnwMv3).toLowerCase(),fresh=Date.parse(f.fldnHjTrnRPfEqM4e||'')>=actionTime;
     const actionDone=fresh&&(actionKind==='Launch'?['active','running','live','scheduled','completed'].includes(actionStatus):actionKind==='Pause'?['paused','inactive'].includes(actionStatus):actionStatus==='deleted');
     const actionTerminal=Date.parse(f.fldqKPdzUqppbItvX||'')>=actionTime&&['completed','failed','error'].includes(clean(f.fldCebt3IMI8ZxdQq).toLowerCase());
     if(!actionDone&&!actionTerminal)fail('Another campaign action is pending. Finish it before topping up.');
    }
    s.resultMessage='Current EmailBison destination and '+s.finalIds.length+' attached senders verified. No sender selection was changed.';
    s.senderSelectionApplied=false;
    return finish(s);
   }
   case 'start':return readRecord(s,'load');
   case 'load':{
    let stored={};try{stored=JSON.parse(b.fields?.[FIELD.state]||'{}');}catch{}
    s.authorized=b.id===s.recordId&&stored.requestId===s.requestId;
    const f=currentRecord(s,b);
    s.campaignId=clean(f[FIELD.campaign]);s.baseUrl=clean(f[FIELD.base]).replace(/\/$/,'');s.apiKey=clean(f[FIELD.key]);
    if(!/^\d+$/.test(s.campaignId)||Number(s.campaignId)<1)fail('Create the EmailBison output campaign first.');
    // Only configured public HTTPS origins may receive the client credential.
    if(!/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$/i.test(s.baseUrl))fail('Set a valid HTTPS EmailBison server.');
    if(!s.apiKey||!Array.isArray(f[FIELD.client])||f[FIELD.client].length!==1)fail('The campaign must have one client and its EmailBison API credential.');
    s.lockKey=s.baseUrl+'/'+s.campaignId;s.stage='locked';return {state:s,action:{kind:'acquire'}};
   }
   case 'locked':
    if(b.duplicate){s.duplicate=true;return finish(s);}
    if(!b.acquired){s.error='Another sender update is running, or this request was already processed. No sender changes were made.';return readRecord(s,'failureRead');}
    s.locked=true;return save(s,'runningSaved','Running','Checking the selected sender accounts.');
   case 'runningSaved':
    s.accountIndex=0;s.senderIds=[];return request(s,'account','airtable','GET',AT+'tblMSOBJ0wMgxSg4l/'+s.senderRecordIds[0]+'?returnFieldsByFieldId=true');
   case 'account':{
    if(b.id!==s.senderRecordIds[s.accountIndex])fail('A sender record did not match the selection.');
    const id=clean(b.fields?.fldR19WUqSSBVQcPO);if(!/^\d+$/.test(id)||Number(id)<1)fail('A selected account has no valid EmailBison sender ID.');
    s.senderIds.push(id);s.accountIndex++;
    if(s.accountIndex<s.senderRecordIds.length)return request(s,'account','airtable','GET',AT+'tblMSOBJ0wMgxSg4l/'+s.senderRecordIds[s.accountIndex]+'?returnFieldsByFieldId=true');
    if(ids(s.senderIds).length!==s.senderIds.length)fail('Two selected Airtable accounts refer to the same EmailBison sender.');
    return list(s,'eligible','/sender-emails');
   }
   case 'eligible':
    if(!pageRows(s,b,'eligible'))return list(s,'eligible','/sender-emails',s.page+1);
    if(s.senderIds.some(id=>!s.eligible.some(a=>a.id===id&&a.status==='connected')))fail('Every selected sender must be connected and accessible in this client’s EmailBison workspace.');
    delete s.eligible;return bison(s,'original','GET','');
   case 'original':
    if(String(b.data?.id)!==s.campaignId)fail('EmailBison returned a different campaign.');
    s.originalStatus=clean(b.data.status).toLowerCase();
    if(!['active','running','queued','paused','draft','completed'].includes(s.originalStatus))fail('This campaign status does not allow a sender update.');
    s.wasRunning=['active','running','queued'].includes(s.originalStatus);
    return list(s,'before','/campaigns/'+s.campaignId+'/sender-emails');
   case 'before':
    if(!pageRows(s,b,'before'))return list(s,'before','/campaigns/'+s.campaignId+'/sender-emails',s.page+1);
    s.originalIds=ids(s.before);delete s.before;
    s.add=s.senderIds.filter(id=>!s.originalIds.includes(id));s.remove=s.originalIds.filter(id=>!s.senderIds.includes(id));
    if(!s.add.length&&!s.remove.length){s.finalIds=s.senderIds;s.noChange=true;return readRecord(s,'completeRead');}
    return readRecord(s,'beforePause');
   case 'beforePause':
    currentRecord(s,b);
    s.pauseAttempted=true;return bison(s,'paused','PATCH','/pause');
   case 'paused':s.poll=0;return bison(s,'pauseCheck','GET','');
   case 'pauseCheck':
    if(String(b.data?.id)!==s.campaignId)fail('Campaign identity did not match after pause.');
    if(clean(b.data.status).toLowerCase()!=='paused'){
     if(++s.poll>=10)fail('EmailBison did not confirm the campaign was paused.');return wait(s,'pauseWait');
    }
    return save(s,'pausedSaved','Running','Campaign paused. Replacing sender accounts.');
   case 'pauseWait':return bison(s,'pauseCheck','GET','');
   case 'pausedSaved':
    if(s.add.length)return bison(s,'added','POST','/attach-sender-emails',{sender_email_ids:s.add});
    s.poll=0;return list(s,'attached','/campaigns/'+s.campaignId+'/sender-emails');
   case 'added':s.poll=0;return list(s,'attached','/campaigns/'+s.campaignId+'/sender-emails');
   case 'attached':
    if(!pageRows(s,b,'attached'))return list(s,'attached','/campaigns/'+s.campaignId+'/sender-emails',s.page+1);
    if(s.senderIds.some(id=>!ids(s.attached).includes(id))){if(++s.poll>=20)fail('New sender accounts did not finish attaching.');return wait(s,'attachWait');}
    return bison(s,'beforeRemove','GET','');
   case 'attachWait':return list(s,'attached','/campaigns/'+s.campaignId+'/sender-emails');
   case 'beforeRemove':
    if(String(b.data?.id)!==s.campaignId||clean(b.data.status).toLowerCase()!=='paused')fail('Campaign was no longer paused before removing senders.');
    if(s.remove.length)return bison(s,'removed','DELETE','/remove-sender-emails',{sender_email_ids:s.remove});
    s.poll=0;return list(s,'final','/campaigns/'+s.campaignId+'/sender-emails');
   case 'removed':s.poll=0;return list(s,'final','/campaigns/'+s.campaignId+'/sender-emails');
   case 'final':
    if(!pageRows(s,b,'final'))return list(s,'final','/campaigns/'+s.campaignId+'/sender-emails',s.page+1);
    if(!equal(ids(s.final),s.senderIds)){if(++s.poll>=30)fail('Attached senders still do not exactly match the selection.');return wait(s,'finalWait');}
    if(s.final.some(a=>a.status!=='connected'))fail('A selected sender disconnected during the update.');
    s.finalIds=ids(s.final);delete s.final;return readRecord(s,'verifiedRead');
   case 'finalWait':return list(s,'final','/campaigns/'+s.campaignId+'/sender-emails');
   case 'verifiedRead':currentRecord(s,b);return bison(s,'verifiedStatus','GET','');
   case 'verifiedStatus':
    if(String(b.data?.id)!==s.campaignId||clean(b.data.status).toLowerCase()!=='paused')fail('The campaign must remain paused until the sender check is complete.');
    if(s.wasRunning)return save(s,'beforeResume','Running','Sender replacement verified. Resuming the previously running campaign.');
    return readRecord(s,'completeRead');
   case 'beforeResume':return bison(s,'resumed','PATCH','/resume');
   case 'resumed':s.poll=0;return bison(s,'resumeCheck','GET','');
   case 'resumeCheck':
    if(String(b.data?.id)!==s.campaignId)fail('Campaign identity did not match after resume.');
    if(!['active','running','queued'].includes(clean(b.data.status).toLowerCase())){if(++s.poll>=10)fail('EmailBison did not confirm resumption.');return wait(s,'resumeWait');}
    s.resumed=true;return readRecord(s,'completeRead');
   case 'resumeWait':return bison(s,'resumeCheck','GET','');
   case 'completeRead':
    currentRecord(s,b);return save(s,'completedSaved','Completed',s.noChange?'The selected senders already match EmailBison. No changes were needed.':s.finalIds.length+' sender accounts verified. '+(s.resumed?'Campaign resumed.':'Campaign remains paused. Use Launch when ready.'));
   case 'completedSaved':return finish(s);
   case 'released':if(b.resource!==s.lockKey)fail('The sender update lock release was not confirmed.');s.locked=false;return finish(s);
   case 'recoverPause':s.recoveryPoll=0;return bison(s,'recoverCheck','GET','');
   case 'recoverCheck':
    s.safelyPaused=String(b.data?.id)===s.campaignId&&clean(b.data.status).toLowerCase()==='paused';
    if(!s.safelyPaused&&++s.recoveryPoll<10)return wait(s,'recoverWait');
    s.holdLock=!s.safelyPaused;return readRecord(s,'failureRead');
   case 'recoverWait':return bison(s,'recoverCheck','GET','');
   case 'failureRead':{
    let f=b.fields||{},saved={};try{saved=JSON.parse(f[FIELD.state]||'{}');}catch{}
    if(saved.requestId!==s.requestId)return finish(s);
    return save(s,'failedSaved','Failed',s.error+' '+(s.safelyPaused?'Campaign is paused.':s.pauseAttempted?'Pause could not be confirmed. Check EmailBison before retrying.':'No sender changes were made.'));
   }
   case 'failedSaved':return finish(s);
   default:fail('Unknown sender update stage.');
  }
 } catch(e) {
  if(['locked','released'].includes(s.stage))s.holdLock=true;
  const msg=String(e.message||'Sender update failed.').slice(0,500);
  // EmailBison applies account changes asynchronously. Restart only mutation-stage
  // snapshots when pagination changes; never accept a partial or mixed snapshot.
  if(['attached','final'].includes(s.stage) && ['Sender accounts changed while pages were being read.','Sender counts did not reconcile across pages.'].includes(msg)) {
   const stage=s.stage; s.snapshotRetries=s.snapshotRetries||{};
   s.snapshotRetries[stage]=(s.snapshotRetries[stage]||0)+1;
   if(s.snapshotRetries[stage]<=10) {
    delete s[stage]; delete s.listTotal; delete s.listLast;
    return wait(s,stage==='attached'?'attachWait':'finalWait');
   }
  }

  if(['failureRead','failedSaved'].includes(s.stage)){s.holdLock=!!s.locked;s.error=msg;return finish(s);}
  if(['recoverPause','recoverCheck','recoverWait'].includes(s.stage)){s.holdLock=true;s.safelyPaused=false;return readRecord(s,'failureRead');}
  return recovery(s,msg);
 }
}

