WITH attempt AS (
 INSERT INTO dulcy_sender_updates.requests(request_id, resource, execution_id, context)
 VALUES ($1,$2,$3,json_build_object('recordId',$4::text,'senderRecordIds',$5::jsonb,'requestedAt',$6::text)) ON CONFLICT DO NOTHING RETURNING request_id
), acquired AS (
 INSERT INTO dulcy_sender_updates.locks(resource,request_id,execution_id)
 SELECT $2,request_id,$3 FROM attempt ON CONFLICT DO NOTHING RETURNING request_id
) SELECT EXISTS(SELECT 1 FROM acquired) AS acquired, NOT EXISTS(SELECT 1 FROM attempt) AS duplicate;

