return [{json:{state:{...lock.context,requestId:lock.request_id,lockKey:lock.resource,executionId:lock.execution_id,baseUrl,campaignId,apiKey,authorized:true,locked:true,stage:row.id===lock.context.recordId&&apiKey&&baseUrl+'/'+campaignId===lock.resource?'interrupted':'cannotRecover'}}}];

const r=$input.first().json;
